/// <summary>
/// Original invoice control modified
/// </summary>
/// <returns>true or false on modification</returns>
public boolean modified()
{
    boolean ret;

    ret = next modified();

    if (ret)
    {
        FormControl ctrl = this;
        FormRun formRun =  ctrl.formRun();
        FormDataSource salesLine_ds = formRun.dataSource(formDataSourceStr(ReturnTable, SalesLine));
        salesLine_ds.research();
    }

    return ret;
}
